<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Consent\Application\Usecase;

use Civi\Lughauth\Features\OAuth\Consent\Domain\ScopePermission;
use Civi\Lughauth\Features\OAuth\Consent\Domain\Gateway\ScopesConsentGateway;

class ScopesConsentUsecase
{
    public function __construct(
        private readonly ScopesConsentGateway $gateway
    ) {
    }

    /**
     * @return ScopePermission[]
     */
    public function pendingScopes(string $tenant, string $username, string $clientId, string $scope): array
    {
        return $this->gateway->pendingScopes($tenant, $username, $clientId, $this->normalizeScopeList(explode(' ', $scope)));
    }

    /**
     * @param string[] $approvedScopes
     */
    public function storeAcceptedScopes(string $tenant, string $username, string $clientId, array $approvedScopes): void
    {
        $this->gateway->storeAcceptedScopes($tenant, $username, $clientId, $this->normalizeScopeList($approvedScopes));
    }

    /**
     * @param array<int, mixed> $values
     *
     * @return string[]
     */
    public function normalizeScopeList(array $values): array
    {
        $scopes = [];
        foreach ($values as $value) {
            $scope = trim((string) $value);
            if ($scope === '') {
                continue;
            }
            $scopes[] = $scope;
        }
        return array_values(array_unique($scopes));
    }

    /**
     * @return string[]
     */
    public function normalizeScopes(string $scope): array
    {
        return $this->normalizeScopeList(explode(' ', $scope));
    }
}
